      ],
      "assessment": {
        "nobel_worthiness": "A fundamental new topological state of matter, with exceptionally clear experimental consequences and broad influence across condensed matter physics.",
        "attribution": "Kane and Mele supplied the decisive quantum-spin-Hall theory, while Molenkamp led seminal experimental realization in HgTe structures.",
        "maturity": "The phenomenon, its topological framework, and related materials have been extensively reproduced and developed over two decades.",
        "uncertainties": [
          "The most appropriate boundary between this recognition and later quantum anomalous Hall work requires careful definition."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B031",
      "proposed_laureates": [
        "David Vanderbilt",
        "Georg Kresse",
        "Peter E. Blöchl"
      ],
      "assessment": {
        "nobel_worthiness": "These methods made predictive first-principles materials calculations practical and reliable on a transformative scale.",
        "attribution": "Vanderbilt developed ultrasoft pseudopotentials, Blöchl introduced PAW, and Kresse made these ideas broadly usable through highly influential implementations.",
        "maturity": "Their impact is demonstrated by decades of routine use, benchmarking, and successful connection between calculated and measured materials properties.",
        "uncertainties": [
          "A methods prize would need to distinguish these contributions carefully from the wider development of density-functional electronic-structure theory."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Max Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Aberration-corrected electron microscopy revolutionized the direct visualization and quantitative analysis of matter at the atomic scale.",
        "attribution": "Rose provided crucial correction concepts, while Haider and Urban were central to their successful experimental realization and dissemination.",
        "maturity": "Atomic-resolution corrected microscopy is an established, independently validated foundation of modern materials research.",
        "uncertainties": [
          "The credit division among theoretical electron-optics pioneers, instrument builders, and later developers is necessarily broad."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B032",
      "proposed_laureates": [
        "Hideo Hosono"
      ],
      "assessment": {
        "nobel_worthiness": "The iron-based superconductors opened an enduring new class of unconventional high-temperature superconductivity and changed the field's theoretical agenda.",
        "attribution": "Hosono's discovery of superconductivity in iron pnictides is unusually clear and central to the candidate contribution.",
        "maturity": "The result has been reproduced across numerous material families and has supported sustained experimental and theoretical study.",
        "uncertainties": [
          "The microscopic pairing mechanism remains incompletely settled."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Large room-temperature tunnel magnetoresistance established a major quantum transport effect with deep physical interest and vast technological consequence.",
        "attribution": "Moodera and Miyazaki made landmark demonstrations of large TMR, while Parkin's work was pivotal to its materials development and device impact.",
        "maturity": "The effect is quantitatively established and underlies mature spintronic technologies.",
        "uncertainties": [
          "The relationship to the earlier Nobel-recognized discovery of giant magnetoresistance would need particularly careful framing."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have achieved extraordinary precision while enabling new tests of fundamental physics and practical timekeeping.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept and Ye made decisive experimental advances toward record performance and broad application.",
        "maturity": "Independent laboratories have confirmed the architecture and achieved sustained performance at the relevant frontier.",
        "uncertainties": [
          "The eventual prize scope must separate the lattice-clock invention from the wider development of optical frequency metrology."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provide one of the clearest realizations of controllable quantum logic, joining foundational quantum physics to an operating technology.",
        "attribution": "Cirac and Zoller gave essential architectures and protocols, while Blatt made landmark experimental demonstrations of scalable ion-trap quantum operations.",
        "maturity": "The platform has repeatedly demonstrated high-fidelity control and remains central to quantum-information science.",
        "uncertainties": [
          "Credit overlaps with the broader and still rapidly developing field of quantum computation."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle graphene revealed an unexpected route to tunable flat-band correlated states and has created a new experimental materials platform.",
        "attribution": "Bistritzer and MacDonald provided the key theory of magic-angle flat bands, and Jarillo-Herrero led the experimental breakthrough.",
        "maturity": "The principal phenomenology has been widely reproduced and extended to related moiré materials.",
        "uncertainties": [
          "The field is comparatively young, and the full microscopic interpretation of several correlated phases remains unsettled."
        ]
      }
    }
  ]
